use crate::model::{parse_receipt, Receipt};

pub fn import_receipts(ids: &[u64], amounts: &[&str]) -> Result<Vec<Receipt>, String> {
    if ids.len() != amounts.len() {
        return Err("receipt and amount counts differ".into());
    }
    ids.iter()
        .zip(amounts)
        .map(|(id, raw)| parse_receipt(*id, raw))
        .collect()
}

