#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Receipt {
    pub id: u64,
    pub cents: u64,
}

pub fn parse_receipt(id: u64, raw: &str) -> Result<Receipt, String> {
    let cents = raw.parse::<u64>().map_err(|_| format!("invalid amount for {id}"))?;
    if cents == 0 {
        return Err(format!("zero amount for {id}"));
    }
    Ok(Receipt { id, cents })
}

